def runtime(tmp_path):
    directory = tmp_path / 'runtimes' / 'g1-abcd1234'
    directory.mkdir(parents=True)
    return directory


def spawns(monkeypatch):
    calls = []
    monkeypatch.setattr(fault_issue.month_audit, 'spawn_issue_filer',
                        lambda path, record: calls.append(record) or True)
    return calls


def test_the_same_exception_is_counted_until_it_recurs(tmp_path, monkeypatch):
    calls = spawns(monkeypatch)
    rt = runtime(tmp_path)
    results = [fault_issue.note_fault(
        rt, signature='TypeError@navigation.py:642:_y_jump_step',
        detail="TypeError('cannot unpack non-iterable NoneType object')",
        chapter=4, now=1000 + index) for index in range(3)]
    assert [row['status'] for row in results] == ['counted', 'counted', 'reported']
    incidents = audit.load_incidents(rt)
    assert len(incidents) == 1
    record = incidents[0]
    assert record['kind'] == 'brain_error'
    assert record['auto_file'] is True
    assert record['confidence'] == 'high'
    assert record['signature'].endswith('_y_jump_step')
    assert record['fault']['count'] == 3
    assert calls == [record]
    assert 'brain例外' in audit._issue_title(record)
    assert '### brain例外' in audit.render(record)


