def test_the_same_signature_after_the_cooldown_files_a_comment_episode(tmp_path, monkeypatch):
    spawns(monkeypatch)
    rt = runtime(tmp_path)
    for index in range(3):
        fault_issue.note_fault(rt, signature='TypeError@navigation.py:642:_y_jump_step',
                               now=1000 + index)
    later = int(1000 + fault_issue.FAULT_COOLDOWN_SECONDS + 100)
    results = [fault_issue.note_fault(
        rt, signature='TypeError@navigation.py:642:_y_jump_step',
        now=later + index, window=fault_issue.FAULT_WINDOW_SECONDS * 100)
        for index in range(3)]
    assert results[0]['status'] == 'reported'
    assert results[-1]['status'] == 'counted'     # cooldown restarted
    incidents = audit.load_incidents(rt)
    assert len(incidents) == 2
    assert incidents[0]['fingerprint'] == incidents[1]['fingerprint']
    assert incidents[0]['incident_id'] != incidents[1]['incident_id']


def test_occurrences_outside_the_window_start_a_new_episode(tmp_path, monkeypatch):
    calls = spawns(monkeypatch)
    rt = runtime(tmp_path)
    for index in range(3):
        fault_issue.note_fault(rt, signature='TypeError@a.py:1:f',
                               now=1000 + index)
    assert len(calls) == 1
    # far apart: the count restarts, so one later failure is not a recurrence
    result = fault_issue.note_fault(
        rt, signature='TypeError@a.py:1:f',
        now=1000 + fault_issue.FAULT_WINDOW_SECONDS + 10)
    assert result['status'] == 'counted'
    assert result['count'] == 1
    assert len(calls) == 1


