def test_the_counter_file_is_bounded_and_malformed_state_is_tolerated(tmp_path):
    rt = runtime(tmp_path)
    for index in range(fault_issue.FAULT_ENTRIES + 8):
        fault_issue.note_fault(rt, signature=f'TypeError@a.py:{index}:f',
                               now=1000 + index)
    saved = json.loads((rt / fault_issue.FAULTS_FILE).read_text(encoding='utf-8'))
    assert len(saved['entries']) <= fault_issue.FAULT_ENTRIES
    (rt / fault_issue.FAULTS_FILE).write_text('{not json', encoding='utf-8')
    result = fault_issue.note_fault(rt, signature='TypeError@a.py:1:f', now=4000)
    assert result['status'] == 'counted'
    assert result['count'] == 1


def test_oversized_counter_state_is_rejected_after_a_bounded_read(tmp_path):
    rt = runtime(tmp_path)
    path = rt / fault_issue.FAULTS_FILE
    path.write_bytes(
        b'{"schema":1,"entries":{}}'
        + b" " * (fault_issue.FAULTS_READ_LIMIT + 1)
    )
    result = fault_issue.note_fault(
        rt, signature="TypeError@a.py:1:f", now=9000
    )
    assert result["status"] == "counted"
    assert result["count"] == 1
    saved = json.loads(path.read_text(encoding="utf-8"))
    assert saved["entries"]["TypeError@a.py:1:f"]["count"] == 1
    assert path.stat().st_size < fault_issue.FAULTS_READ_LIMIT


def test_exception_signature_uses_fallback_without_traceback():
    exc = TypeError("unraised")
    signature = fault_issue.exception_signature(exc, "fallback.py:12:handler")
    assert signature == "TypeError@fallback.py:12:handler"


def test_exception_signature_names_the_class_and_innermost_frame():
    try:
        raise TypeError('cannot unpack non-iterable NoneType object')
    except TypeError as exc:
        signature = fault_issue.exception_signature(exc, 'fallback')
    assert signature.startswith('TypeError@test_hanjuku_fault_issue.py:')
    assert signature.endswith('test_exception_signature_names_the_class_and_innermost_frame')


class FakeGh:
    def __init__(self):
        self.calls = []
        self.body = None

    def __call__(self, args):
        self.calls.append(list(args))
        if args[:2] == ['auth', 'status']:
            return 0, '', ''
        if args[:2] == ['issue', 'list']:
            return 0, json.dumps([]), ''
        if args[:2] == ['issue', 'create']:
            index = args.index('--body-file')
            self.body = Path(args[index + 1]).read_text(encoding='utf-8')
            return 0, 'https://github.com/azumag/docich/issues/1', ''
        return 1, '', 'unexpected'


def test_the_existing_filer_creates_the_issue_with_labels(tmp_path, monkeypatch):
    spawns(monkeypatch)
    rt = runtime(tmp_path)
    for index in range(3):
        fault_issue.note_fault(rt, signature='TypeError@navigation.py:642:_y_jump_step',
                               chapter=4, now=5000 + index)
    gh = FakeGh()
    result = audit.file_issue(rt, gh=gh, scanner=lambda path: True,
                              now=time.time())
    assert result['status'] == 'created'
    create = [call for call in gh.calls if call[:2] == ['issue', 'create']][0]
    assert '--label' in create and 'auto-generated' in create
    title = create[create.index('--title') + 1]
    assert 'brain例外で入力停止が再発' in title
    assert '<!-- hanjuku-month-audit fingerprint=' in gh.body
    assert '### brain例外' in gh.body
